solution:
function maxProfit(prices) {
  let cheapestSoFar = Infinity; // lowest price on any earlier day
  let bestProfit = 0;
  for (const price of prices) {
    const profitIfSoldToday = price - cheapestSoFar;
    if (profitIfSoldToday > bestProfit) bestProfit = profitIfSoldToday;
    if (price < cheapestSoFar) cheapestSoFar = price;
  }
  return bestProfit;
}

